	if len(links) != 1 || links[0].URL != "https://visible.com" {
		t.Errorf("links = %v, want one link to https://visible.com", links)
	}
	if len(tables) != 1 {
		t.Errorf("tables length = %d, want 1", len(tables))
	}
}
